INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000004,'{"id":760100000000004,"title":"B2 · Разговорный · Знакомство и этикет · Mission 4","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["испытывать смешанные чувства","прийти к выводу","ответить тактично","выразить иначе"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["express a reservation","make a valid point","come to a conclusion","weigh up the options"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["прояснить предположение","разобраться с недопониманием","выразить иначе","ответить тактично"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["выразить сомнение","разобраться с недопониманием","взвесить варианты","ответить тактично"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["clarify an assumption","express a reservation","have mixed feelings","respond tactfully"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выраз