INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000008,'{"id":760100000000008,"title":"A2 · Разговорный · Повседневные ситуации · Mission 8","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"🎯","xp":27,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"6 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «I agree».","options":["не торопись","что ты думаешь?","это зависит от обстоятельств","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «не торопись»?","options":["by the way","I am not sure","I am looking for","take your time"],"correctAnswer":"take your time","explanation":"«take your time» — «не торопись».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["что ты думаешь?","я не согласен","можно мне","я не уверен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «I would like».","options":["я бы хотел","что ты думаешь?","начнём?","дай мне знать"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «я ищу»?","options":["take your time","it depends","I agree","I am looking for"],"correctAnswer":"I am looking for","explanation":"«I am looking for» — «я ищу».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я не уверен","начнём?","я не согласен","дай мне знать"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «could I have».","options":["дай мне знать","я не согласен","можно мне","это зависит от обстоятельств"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["I am looking for","could I have","it depends","take your time"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000009,'{"id":760100000000009,"title":"B1 · Разговорный · Повседневные ситуации · Mission 9","description":"B1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":32,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["по моему мнению","поддерживать связь","принимать участие в","это звучит разумно"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["keep in touch","to be honest","in my opinion","make a suggestion"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["поддерживать связь","с нетерпением ждать","прояснить недоразумение","насколько мне известно"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «make a suggestion».","options":["это звучит разумно","предложить идею","принимать участие в","поддерживать связь"],"correctAnswer":"предложить идею","explanation":"«make a suggestion» — «предложить идею».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «принимать участие в»?","options":["on the other hand","in my opinion","make a suggestion","take part in"],"correctAnswer":"take part in","explanation":"«take part in» — «принимать участие в».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «on the other hand».","options":["предложить идею","с другой стороны","это звучит разумно","принимать участие в"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","с нетерпением ждать","принимать участие в","я понимаю твою точку зрения"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «с нетерпением ждать»?","options":["in my opinion","look forward to","keep in touch","clear up a misunderstanding"],"correctAnswer":"look forward to","explanation":"«look forward to» — «с нетерпением ждать».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000010,'{"id":760100000000010,"title":"B2 · Разговорный · Повседневные ситуации · Mission 10","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["найти баланс","прояснить предположение","разобраться с недопониманием","ответить тактично"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["express a reservation","take into account","have mixed feelings","weigh up the options"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «strike a balance».","options":["испытывать смешанные чувства","выразить обеспокоенность","найти баланс","взвесить варианты"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["привести веский аргумент","испытывать смешанные чувства","выразить иначе","принять во внимание"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «взвесить варианты»?","options":["strike a balance","weigh up the options","address a misunderstanding","clarify an assumption"],"correctAnswer":"weigh up the options","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["прояснить предположение","взвесить варианты","принять во внимание","привести веский аргумент"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","выразить иначе","выразить обеспокоенность","прийти к выводу"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["take into account","come to a conclusion","have mixed feelings","put it another way"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000011,'{"id":760100000000011,"title":"C1 · Разговорный · Повседневные ситуации · Mission 11","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":45,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «adapt the register».","options":["модерировать обсуждение","подобрать стиль общения","развернуть мысль","оспорить предположение"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["challenge an assumption","moderate a discussion","convey a subtle distinction","elaborate on a point"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["сформулировать вопрос нейтрально","уточнить оговорками утверждение","подобрать стиль общения","признать обоснованность довода"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["уточнить оговорками утверждение","развернуть мысль","модерировать обсуждение","найти точки соприкосновения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «сделать вывод»?","options":["concede a point","frame a question neutrally","acknowledge a counterargument","draw an inference"],"correctAnswer":"draw an inference","explanation":"«draw an inference» — «сделать вывод».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["найти точки соприкосновения","признать обоснованность довода","передать тонкое различие","признать контраргумент"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["развернуть мысль","оспорить предположение","сформулировать вопрос нейтрально","подобрать стиль общения"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["convey a subtle distinction","frame a question neutrally","qualify a statement","elaborate on a point"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000012,'{"id":760100000000012,"title":"C2 · Разговорный · Повседневные ситуации · Mission 12","description":"C2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":47,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["согласовать разные точки зрения","синтезировать противоположные взгляды","выдвинуть на первый план последствия","оспорить исходную предпосылку"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «избегать необоснованной уверенности»?","options":["expose a false dichotomy","avoid unwarranted certainty","reach a considered judgement","reconcile competing perspectives"],"correctAnswer":"avoid unwarranted certainty","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["синтезировать противоположные взгляды","разграничить намерение и результат","прийти к взвешенному суждению","выдвинуть на первый план последствия"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["избегать необоснованной уверенности","выдвинуть на первый план последствия","провести тонкое различие","разграничить намерение и результат"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» —