INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000014,'{"id":760100000000014,"title":"A2 · Разговорный · Мнение и общение · Mission 14","description":"A2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"🎯","xp":27,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"6 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «I disagree».","options":["что ты думаешь?","я согласен","я не согласен","можно мне"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["I am looking for","I disagree","by the way","I am not sure"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «I would like».","options":["кстати","что ты думаешь?","я бы хотел","дай мне знать"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «I agree».","options":["это зависит от обстоятельств","не торопись","можно мне","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["it depends","I agree","shall we start?","by the way"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «take your time».","options":["я не уверен","начнём?","не торопись","это зависит от обстоятельств"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «what do you think?».","options":["что ты думаешь?","не торопись","дай мне знать","я согласен"],"correctAnswer":"что ты думаешь?","explanation":"«what do you think?» — «что ты думаешь?».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «я не уверен»?","options":["I disagree","I am not sure","let me know","what do you think?"],"correctAnswer":"I am not sure","explanation":"«I am not sure» — «я не уверен».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000015,'{"id":760100000000015,"title":"B1 · Разговорный · Мнение и общение · Mission 15","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":32,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «look forward to».","options":["с нетерпением ждать","это звучит разумно","если честно","насколько мне известно"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["to be honest","keep in touch","as far as I know","in my opinion"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «take part in».","options":["я понимаю твою точку зрения","достичь соглашения","с нетерпением ждать","принимать участие в"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["принимать участие в","достичь соглашения","это звучит разумно","насколько мне известно"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["keep in touch","that sounds reasonable","look forward to","to be honest"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «keep in touch».","options":["предложить идею","прояснить недоразумение","поддерживать связь","с другой стороны"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «I see your point».","options":["я понимаю твою точку зрения","это звучит разумно","с другой стороны","прояснить недоразумение"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["look forward to","that sounds reasonable","on the other hand","in my opinion"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000016,'{"id":760100000000016,"title":"B2 · Разговорный · Мнение и общение · Mission 16","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":40,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["испытывать смешанные чувства","ответить тактично","разобраться с недопониманием","найти баланс"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["come to a conclusion","put it another way","respond tactfully","clarify an assumption"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["привести веский аргумент","испытывать смешанные чувства","взвесить варианты","прояснить предположение"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить сомнение","найти баланс","выразить обеспокоенность","испытывать смешанные чувства"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["express a reservation","respond tactfully","make a valid point","weigh up the options"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить иначе","выразить сомнение","взвесить варианты","выразить обеспокоенность"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «strike a balance».","options":["выразить обеспокоенность","найти баланс","разобраться с недопониманием","испытывать смешанные чувства"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «взвесить варианты»?","options":["weigh up the options","respond tactfully","strike a balance","express a reservation"],"correctAnswer":"weigh up the options","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000017,'{"id":760100000000017,"title":"C1 · Разговорный · Мнение и общение · Mission 17","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":42,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «draw an inference».","options":["выражаться точно","сделать вывод","найти точки соприкосновения","уточнить оговорками утверждение"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["draw an inference","frame a question neutrally","qualify a statement","convey a subtle distinction"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «moderate a discussion».","options":["модерировать обсуждение","развернуть мысль","сформулировать вопрос нейтрально","сделать вывод"],"correctAnswer":"модерировать обсуждение","explanation":"«moderate a discussion» — «модерировать обсуждение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["сформулировать вопрос нейтрально","уточнить оговорками утверждение","развернуть мысль","признать контраргумент"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «подобрать стиль общения»?","options":["adapt the register","moderate a discussion","concede a point","acknowledge a counterargument"],"correctAnswer":"adapt the register","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «speak with precision».","options":["найти точки соприкосновения","признать обоснованность довода","развернуть мысль","выражаться точно"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["найти точки соприкосновения","передать тонкое различие","сформулировать вопрос нейтрально","уточнить оговорками утверждение"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["draw an inference","moderate a discussion","challenge an assumption","convey a subtle distinction"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000018,'{"id":760100000000018,"title":"C2 · Разговорный · Мнение и общение · Mission 18","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":47,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["синтезировать противоположные взгляды","согласовать разные точки зрения","выдвинуть на первый план последствия","прийти к взвешенному суждению"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «синтезировать противоположные взгляды»?","options":["synthesise opposing views","reach a considered judgement","challenge the underlying premise","avoid unwarranted certainty"],"correctAnswer":"synthesise opposing views","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["прийти к взвешенному суждению","сформулировать оговорку","оспорить исходную предпосылку","выявить ложную дихотомию"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["оспорить исходную предпосылку","избегать необоснованной уверенности","синтезировать противоположные взгляды","выдвинуть на первый план последствия"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["expose a false dichotomy","challenge the underlying premise","synthesise opposing views","make a nuanced distinction"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["согласовать разные точки зрения","прийти к взвешенному суждению","сохранять риторическую сдержанность","предложить ответ с оговорками"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["синтезировать противоположные взгляды","прийти к взвешенному суждению","согласовать разные точки зрения","оспорить исходную предпосылку"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «провести тонкое различие»?","options":["expose a false dichotomy","make a nuanced distinction","avoid unwarranted certainty","synthesise opposing views"],"correctAnswer":"make a nuanced distinction","explanation":"«make a nuanced distinction» — «провести тонкое различие».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
