INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000021,'{"id":760100000000021,"title":"B1 · Разговорный · Диалог и уточнение · Mission 21","description":"B1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":35,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","поддерживать связь","с нетерпением ждать","принимать участие в"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «поддерживать связь»?","options":["reach an agreement","clear up a misunderstanding","on the other hand","keep in touch"],"correctAnswer":"keep in touch","explanation":"«keep in touch» — «поддерживать связь».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «as far as I know».","options":["достичь соглашения","насколько мне известно","по моему мнению","принимать участие в"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «in my opinion».","options":["если честно","достичь соглашения","поддерживать связь","по моему мнению"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["clear up a misunderstanding","take part in","I see your point","on the other hand"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «