INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000022,'{"id":760100000000022,"title":"B2 · Разговорный · Диалог и уточнение · Mission 22","description":"B2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «express a reservation».","options":["ответить тактично","прийти к выводу","выразить обеспокоенность","выразить сомнение"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["respond tactfully","have mixed feelings","address a misunderstanding","put it another way"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «take into account».","options":["ответить тактично","принять во внимание","испытывать смешанные чувства","привести веский аргумент"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["испытывать смешанные чувства","привести веский аргумент","разобраться с недопониманием","прояснить предположение"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["strike a balance","respond tactfully","make a valid point","have mixed feelings"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично».","type":"choice"},{"