INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000023,'{"id":760100000000023,"title":"C1 · Разговорный · Диалог и уточнение · Mission 23","description":"C1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":42,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «adapt the register».","options":["сформулировать вопрос нейтрально","подобрать стиль общения","сделать вывод","модерировать обсуждение"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["convey a subtle distinction","challenge an assumption","adapt the register","build common ground"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["уточнить оговорками утверждение","признать обоснованность довода","оспорить предположение","найти точки соприкосновения"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["признать контраргумент","признать обоснованность довода","оспорить предположение","найти точки соприкосновения"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["speak with precision","adapt the register","build common ground","concede a point"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["оспорить предположение","выражаться точно","передать тонкое различие","развернуть мысль"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["передать тонкое различие","сформулировать вопрос нейтрально","оспорить предположение","сделать вывод"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["concede a point","build common ground","frame a question neutrally","qualify a statement"],"correctAnswer":"build common ground","explanation":"«build common ground» — «найти точки соприкосновения».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000024,'{"id":760100000000024,"title":"C2 · Разговорный · Диалог и уточнение · Mission 24","description":"C2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":47,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["согласовать разные точки зрения","выдвинуть на первый план последствия","провести тонкое различие","сохранять риторическую сдержанность"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «избегать необоснованной уверенности»?","options":["articulate a caveat","avoid unwarranted certainty","foreground the implications","challenge the underlying premise"],"correctAnswer":"avoid unwarranted certainty","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["оспорить исходную предпосылку","разграничить намерение и результат","выдвинуть на первый план последствия","прийти к взвешенному суждению"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["сформулировать оговорку","избегать необоснованной уверенности","выявить ложную дихотомию","согласовать разные точки зрения"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «сформулировать оговорку»?","options":["expose a false dichotomy","foreground the implications","articulate a caveat","reconcile competing perspectives"],"correctAnswer":"articulate a caveat","explanation":"«articulate a caveat» — «сформулировать оговорку».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["выявить ложную дихотомию","синтезировать противоположные взгляды","разграничить намерение и результат","предложить ответ с оговорками"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["согласовать разные точки зрения","разграничить намерение и результат","синтезировать противоположные взгляды","прийти к взвешенному суждению"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["invite a qualified response","foreground the implications","challenge the underlying premise","reconcile competing perspectives"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
