INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000026,'{"id":760100000000026,"title":"A2 · Разговорный · Точность высказывания · Mission 26","description":"A2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"🎯","xp":30,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"6 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «take your time».","options":["не торопись","я бы хотел","это зависит от обстоятельств","дай мне знать"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["what do you think?","I disagree","I would like","I am not sure"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «it depends».","options":["это зависит от обстоятельств","я не согласен","я согласен","я бы хотел"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «I agree».","options":["я не уверен","я бы хотел","дай мне знать","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «можно мне»?","options":["I agree","take your time","by the way","could I have"],"correctAnswer":"could I have","explanation":"«could I have» — «можно мне».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «let me know».","options":["не торопись","дай мне знать","я не уверен","я согласен"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать».","type":"choice