INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000027,'{"id":760100000000027,"title":"B1 · Разговорный · Точность высказывания · Mission 27","description":"B1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":32,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «I see your point».","options":["с нетерпением ждать","насколько мне известно","достичь соглашения","я понимаю твою точку зрения"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["I see your point","in my opinion","reach an agreement","make a suggestion"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["насколько мне известно","по моему мнению","это звучит разумно","с нетерпением ждать"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «as far as I know».","options":["с другой стороны","по моему мнению","поддерживать связь","насколько мне известно"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «прояснить недоразумение»?","options":["on the other hand","clear up a misunderstanding","I see your point","in my opinion"],"correctAnswer":"clear up a misunderstanding","explanation":"«clear up a misunderstanding» — «прояснить недоразумение».","type":