INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000028,'{"id":760100000000028,"title":"B2 · Разговорный · Точность высказывания · Mission 28","description":"B2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить сомнение","найти баланс","выразить обеспокоенность","ответить тактично"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["have mixed feelings","address a misunderstanding","make a valid point","take into account"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["выразить сомнение","выразить обеспокоенность","принять во внимание","ответить тактично"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","принять во внимание","ответить тактично","прийти к выводу"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["have mixed feelings","come to a conclusion","strike a balance","express a reservation"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «express a reservation».","options":["принять во внимание","испытывать смешанные чувства","разобраться с недопониманием","выразить сомнение"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["испытывать смешанные чувства","привести веский аргумент","взвесить варианты","разобраться с недопониманием"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["respond tactfully","address a misunderstanding","clarify an assumption","put it another way"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000029,'{"id":760100000000029,"title":"C1 · Разговорный · Точность высказывания · Mission 29","description":"C1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":42,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «concede a point».","options":["выражаться точно","признать обоснованность довода","передать тонкое различие","подобрать стиль общения"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["frame a question neutrally","challenge an assumption","moderate a discussion","speak with precision"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «build common ground».","options":["сформулировать вопрос нейтрально","передать тонкое различие","оспорить предположение","найти точки соприкосновения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «adapt the register».","options":["сформулировать вопрос нейтрально","модерировать обсуждение","признать обоснованность довода","подобрать стиль общения"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["frame a question neutrally","moderate a discussion","adapt the register","elaborate on a point"],