INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000030,'{"id":760100000000030,"title":"C2 · Разговорный · Точность высказывания · Mission 30","description":"C2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":47,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["выдвинуть на первый план последствия","согласовать разные точки зрения","предложить ответ с оговорками","синтезировать противоположные взгляды"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «выдвинуть на первый план последствия»?","options":["articulate a caveat","reach a considered judgement","avoid unwarranted certainty","foreground the implications"],"correctAnswer":"foreground the implications","explanation":"«foreground the implications» — «выдвинуть на первый план последствия».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «distinguish intent from impact».","options":["разграничить намерение и результат","согласовать разные точки зрения","предложить ответ с оговорками","избегать необоснованной уверенности"],"correctAnswer":"разграничить намерение и результат","explanation":"«distinguish intent from impact» — «разграничить намерение и результат».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["прийти к взвешенному суждению","сформулировать оговорку","сохранять риторическую сдержанность","избегать необоснованной уверенности"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти 