INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000032,'{"id":760100000000032,"title":"A2 · Разговорный · Знакомство и этикет · Mission 32","description":"A2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"🎯","xp":27,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"6 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «I would like».","options":["я бы хотел","я не уверен","я не согласен","это зависит от обстоятельств"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «я не согласен»?","options":["I am looking for","I disagree","take your time","could I have"],"correctAnswer":"I disagree","explanation":"«I disagree» — «я не согласен».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «I am looking for».","options":["я бы хотел","я согласен","я ищу","начнём?"],"correctAnswer":"я ищу","explanation":"«I am looking for» — «я ищу».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «could I have».","options":["можно мне","я бы хотел","кстати","я ищу"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["what do you think?","by the way","shall we start?","I agree"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «it depends».","options":["я ищу","я не согласен","это зависит от обстоятельств","дай мне знать"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «take your time».","options":["я ищу","можно мне","я не уверен","не торопись"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «я не уверен»?","options":["I am not sure","I agree","shall we start?","I am looking for"],"correctAnswer":"I am not sure","explanation":"«I am not sure» — «я не уверен».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000033,'{"id":760100000000033,"title":"B1 · Разговорный · Знакомство и этикет · Mission 33","description":"B1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":32,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","с нетерпением ждать","если честно","я понимаю твою точку зрения"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["make a suggestion","keep in touch","on the other hand","look forward to"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «on the other hand».","options":["с другой стороны","с нетерпением ждать","я понимаю твою точку зрения","прояснить недоразумение"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «as far as I know».","options":["насколько мне известно","принимать участие в","поддерживать связь","это звучит разумно"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["reach an agreement","take part in","on the other hand","that sounds reasonable"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","это звучит разумно","с другой стороны","принимать участие в"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «keep in touch».","options":["это звучит разумно","поддерживать связь","по моему мнению","принимать участие в"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «с нетерпением ждать»?","options":["that sounds reasonable","look forward to","keep in touch","make a suggestion"],"correctAnswer":"look forward to","explanation":"«look forward to» — «с нетерпением ждать».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000034,'{"id":760100000000034,"title":"B2 · Разговорный · Знакомство и этикет · Mission 34","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","разобраться с недопониманием","выразить сомнение","выразить обеспокоенность"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «взвесить варианты»?","options":["put it another way","raise a concern","weigh up the options","address a misunderstanding"],"correctAnswer":"weigh up the options","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «strike a balance».","options":["ответить тактично","испытывать смешанные чувства","взвесить варианты","найти баланс"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["выразить сомнение","ответить тактично","привести веский аргумент","испытывать смешанные чувства"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["make a valid point","come to a conclusion","raise a concern","clarify an assumption"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить сомнение","принять во внимание","разобраться с недопониманием","испытывать смешанные чувства"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «take into account».","options":["принять во внимание","выразить обеспокоенность","ответить тактично","прояснить предположение"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["strike a balance","clarify an assumption","address a misunderstanding","take into account"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000035,'{"id":760100000000035,"title":"C1 · Разговорный · Знакомство и этикет · Mission 35","description":"C1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":42,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["выражаться точно","оспорить предположение","сформулировать вопрос нейтрально","признать контраргумент"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["concede a point","draw an inference","moderate a discussion","elaborate on a point"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «adapt the register».","options":["признать контраргумент","сделать вывод","найти точки соприкосновения","подобрать стиль общения"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["признать обоснованность довода","оспорить предположение","развернуть мысль","модерировать обсуждение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["build common ground","acknowledge a counterargument","moderate a discussion","draw an inference"],"correctAns