INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000036,'{"id":760100000000036,"title":"C2 · Разговорный · Знакомство и этикет · Mission 36","description":"C2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":50,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["предложить ответ с оговорками","прийти к взвешенному суждению","согласовать разные точки зрения","провести тонкое различие"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["challenge the underlying premise","articulate a caveat","avoid unwarranted certainty","foreground the implications"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["предложить ответ с оговорками","разграничить намерение и результат","избегать необоснованной уверенности","синтезировать противоположные взгляды"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["сохранять риторическую сдержанность","оспорить исходную предпосылку","провести тонкое различие","избегать необоснованной уверенности"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую с