INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000038,'{"id":760100000000038,"title":"A2 · Разговорный · Повседневные ситуации · Mission 38","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"🎯","xp":27,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"6 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «I agree».","options":["я не согласен","дай мне знать","можно мне","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["let me know","it depends","I agree","I would like"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["я бы хотел","я не согласен","я согласен","я ищу"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «take your time».","options":["не торопись","я не уверен","это зависит от обстоятельств","дай мне знать"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «начнём?»?","options":["what do you think?","I agree","shall we start?","I would like"],"correctAnswer":"shall we start?","explanation":"«shall we start?» — «начнём?».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «I am not sure».","options":["начнём?","я ищу","кстати","я не уверен"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «let me know».","options":["кстати","не торопись","дай мне знать","начнём?"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["I am looking for","what do you think?","by the way","let me know"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
