INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000040,'{"id":760100000000040,"title":"B2 · Разговорный · Повседневные ситуации · Mission 40","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":37,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить иначе","прояснить предположение","выразить обеспокоенность","взвесить варианты"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["address a misunderstanding","make a valid point","put it another way","respond tactfully"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["найти баланс","прояснить предположение","взвесить варианты","ответить тактично"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить сомнение","испытывать смешанные чувства","взвесить варианты","выразить иначе"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["have mixed feelings","clarify an assumption","raise a concern","address a misunderstanding"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["испытывать смешанные чувства","прояснить предположение","разобраться с недопониманием","принять во внимание"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «strike a balance».","options":["выразить иначе","найти баланс","привести веский аргумент","прояснить предположение"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["address a misunderstanding","raise a concern","express a reservation","weigh up the options"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000041,'{"id":760100000000041,"title":"C1 · Разговорный · Повседневные ситуации · Mission 41","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":45,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «speak with precision».","options":["сформулировать вопрос нейтрально","выражаться точно","признать контраргумент","уточнить оговорками утверждение"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["qualify a statement","moderate a discussion","build common ground","frame a question neutrally"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["признать контраргумент","оспорить предположение","выражаться точно","развернуть мысль"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «draw an inference».","options":["модерировать обсуждение","выражаться точно","подобрать стиль общения","сделать вывод"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["build common ground","moderate a discussion","convey a subtle distinction","elaborate on a point"],"correctAnswer":"moderate a discussion","explana