INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000045,'{"id":760100000000045,"title":"B1 · Разговорный · Мнение и общение · Mission 45","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"🎯","xp":32,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"7 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «keep in touch».","options":["достичь соглашения","прояснить недоразумение","по моему мнению","поддерживать связь"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["as far as I know","make a suggestion","keep in touch","that sounds reasonable"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «look forward to».","options":["насколько мне известно","с нетерпением ждать","принимать участие в","с другой стороны"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «in my opinion».","options":["с другой стороны","если честно","по моему мнению","я понимаю твою точку зрения"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["keep in touch","I see your point","on the other hand","that sounds reasonable"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["с нетерпе