INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000046,'{"id":760100000000046,"title":"B2 · Разговорный · Мнение и общение · Mission 46","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"🎯","xp":40,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["выразить иначе","взвесить варианты","прийти к выводу","привести веский аргумент"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["put it another way","take into account","clarify an assumption","weigh up the options"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["прояснить предположение","принять во внимание","взвесить варианты","прийти к выводу"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["принять во внимание","разобраться с недопониманием","прояснить предположение","испытывать смешанные чувства"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["strike a balance","take into account","weigh up the options","raise a concern"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить иначе","выразить сомнение","выразить обеспокоенность","прийти к выводу"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «express a reservation».","options":["ответить тактично","найти баланс","выразить сомнение","привести веский аргумент"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «принять во внимание»?","options":["express a reservation","weigh up the options","clarify an assumption","take into account"],"correctAnswer":"take into account","explanation":"«take into account» — «принять во внимание».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000047,'{"id":760100000000047,"title":"C1 · Разговорный · Мнение и общение · Mission 47","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"🎯","xp":42,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["найти точки соприкосновения","признать контраргумент","сформулировать вопрос нейтрально","подобрать стиль общения"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «признать контраргумент»?","options":["elaborate on a point","concede a point","acknowledge a counterargument","adapt the register"],"correctAnswer":"acknowledge a counterargument","explanation":"«acknowledge a counterargument» — «признать контраргумент».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["признать контраргумент","передать тонкое различие","сделать вывод","оспорить предположение"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «adapt the register».","options":["уточнить оговорками утверждение","оспорить предположение","сформулировать вопрос нейтрально","подобрать стиль общения"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["concede a point","qualify a statement","elaborate on a point","mo