INSERT OR IGNORE INTO missions(id,data,updated_at) VALUES (760100000000048,'{"id":760100000000048,"title":"C2 · Разговорный · Мнение и общение · Mission 48","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"🎯","xp":47,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","tasks":[{"id":1,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["предложить ответ с оговорками","сохранять риторическую сдержанность","провести тонкое различие","сформулировать оговорку"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку».","type":"choice"},{"id":2,"question":"Какое выражение на британском английском соответствует «сохранять риторическую сдержанность»?","options":["avoid unwarranted certainty","reach a considered judgement","distinguish intent from impact","maintain rhetorical restraint"],"correctAnswer":"maintain rhetorical restraint","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность».","type":"choice"},{"id":3,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["провести тонкое различие","выявить ложную дихотомию","согласовать разные точки зрения","выдвинуть на первый план последствия"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения».","type":"choice"},{"id":4,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["выдвинуть на первый план последствия","синтезировать противоположные взгляды","выявить ложную дихотомию","согласовать разные точки зрения"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды».","type":"choice"},{"id":5,"question":"Какое выражение на британском английском соответствует «прийти к взвешенному суждению»?","options":["avoid unwarranted certainty","reach a considered judgement","articulate a caveat","foreground the implications"],"correctAnswer":"reach a considered judgement","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению».","type":"choice"},{"id":6,"question":"Выбери точное русское значение выражения «distinguish intent from impact».","options":["разграничить намерение и результат","провести тонкое различие","избегать необоснованной уверенности","согласовать разные точки зрения"],"correctAnswer":"разграничить намерение и результат","explanation":"«distinguish intent from impact» — «разграничить намерение и результат».","type":"choice"},{"id":7,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["провести тонкое различие","оспорить исходную предпосылку","предложить ответ с оговорками","выдвинуть на первый план последствия"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие».","type":"choice"},{"id":8,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["expose a false dichotomy","maintain rhetorical restraint","articulate a caveat","invite a qualified response"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию».","type":"choice"}],"shuffleAnswers":false}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
